<script setup lang="ts">
import { useIamManage } from '../composables/useIamManage'
const {canManage,account}=useIamManage()
const page=ref(1),total=ref(0)
function searchRows(){page.value=1;load()}
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import client from '../api/client'
import TableActionButton from '../components/TableActionButton.vue'

const rows=ref<any[]>([]),catalog=ref<any[]>([]),loading=ref(false),dialog=ref(false),saving=ref(false),form=ref<any>({})
async function load(){loading.value=true;try{const requestTime=Date.now();const [roles,perms]=await Promise.all([client.get('/roles/',{params:{page:page.value,page_size:20,_t:requestTime}}),client.get('/roles/permission-catalog/',{params:{_t:requestTime}})]);rows.value=roles.data.results||roles.data;total.value=roles.data.count??rows.value.length;catalog.value=perms.data}catch(e:any){ElMessage.error(e.response?.data?.message||e.response?.data?.detail||'角色加载失败')}finally{loading.value=false}}
function add(){form.value={name:'',code:'',description:'',permissions:[],data_scope:'SELF',is_enabled:true};dialog.value=true}
function edit(row:any){form.value={...row,permissions:[...(row.effective_permissions||row.permissions||[])]};dialog.value=true}
async function save(){if(!form.value.name||!form.value.code)return ElMessage.warning('请填写角色名称和编码');saving.value=true;try{const payload={...form.value};if(payload.is_system_role)delete payload.permissions;payload.id?await client.patch(`/roles/${payload.id}/`,payload):await client.post('/roles/',payload);dialog.value=false;ElMessage.success('角色权限保存成功');await load()}catch(e:any){ElMessage.error(JSON.stringify(e.response?.data?.details||e.response?.data||'保存失败'))}finally{saving.value=false}}
async function remove(row:any){if(row.user_count||row.is_system_role)return ElMessage.warning('系统角色或已分配角色不能删除');try{await ElMessageBox.confirm(`确定删除角色“${row.name}”吗？`,'删除角色',{type:'warning'});await client.delete(`/roles/${row.id}/`);ElMessage.success('角色已删除');load()}catch(e:any){if(e==='cancel'||e==='close')return;ElMessage.error(JSON.stringify(e.response?.data||'删除失败'))}}

const permissionCount=(r:any)=>(r.effective_permissions||r.permissions||[]).length

onMounted(load)
</script>
<template><section><div class="page-head"><div><h2 class="page-title">角色管理</h2><div class="page-subtitle">按模块分配功能权限；仅可授予自身拥有的权限</div></div><div class="toolbar"><el-button @click="searchRows">刷新</el-button><el-button v-if="canManage" type="primary" @click="add">＋ 新增角色</el-button></div></div><el-card><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="name" label="角色名称" min-width="170"/><el-table-column prop="code" label="角色编码" width="160"/><el-table-column label="权限数" width="100"><template #default="s">{{permissionCount(s.row)}}</template></el-table-column><el-table-column prop="user_count" label="用户数" width="100"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.is_enabled?'success':'info'">{{s.row.is_enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="s"><div class="actions"><TableActionButton v-if="canManage&&(account.is_superuser||!s.row.is_system_role)" icon="edit" label="编辑" tone="primary" @click="edit(s.row)"/><TableActionButton v-if="canManage" icon="delete" :disabled="s.row.is_system_role||!!s.row.user_count" label="删除" tone="danger" icon-only @click="remove(s.row)"/></div></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load"/></el-card><el-dialog v-model="dialog" :title="form.id?'编辑角色':'新增角色'" width="720px"><el-alert v-if="form.is_system_role" title="系统角色的编码和权限固定；可创建自定义角色配置权限。" type="info" :closable="false"/><el-form label-position="top"><div class="grid"><el-form-item label="角色名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="角色编码" required><el-input v-model="form.code" :disabled="form.is_system_role" placeholder="如 OPS_ADMIN"/></el-form-item><el-form-item label="启用角色"><el-switch v-model="form.is_enabled"/></el-form-item></div><el-form-item label="角色说明"><el-input v-model="form.description" type="textarea" :rows="2"/></el-form-item><div class="permission-title">功能权限</div><div class="permission-groups"><div v-for="group in catalog" :key="group.group" class="permission-group"><b>{{group.group}}</b><el-checkbox-group v-model="form.permissions" :disabled="form.is_system_role"><el-checkbox v-for="item in group.items" :key="item[0]" :value="item[0]">{{item[1]}}</el-checkbox></el-checkbox-group></div></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存角色</el-button></template></el-dialog></section></template>
<style scoped>.page-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.actions{display:flex;gap:6px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.permission-title{font-weight:700;margin:5px 0 10px}.permission-groups{border:1px solid #e1e7ee;border-radius:5px}.permission-group{display:grid;grid-template-columns:120px 1fr;padding:13px 16px}.permission-group+.permission-group{border-top:1px solid #e8edf2}.permission-group b{font-size:13px}.el-checkbox{min-width:180px}@media(max-width:700px){.grid{grid-template-columns:1fr}.permission-group{grid-template-columns:1fr;gap:10px}}
</style>
